// ❌ OLD: setTimeout(fn, 0) and requestIdleCallback are unreliable:
// setTimeout competes with critical tasks, and requestIdleCallback can be
// delayed indefinitely on busy tabs.
function logUserInteraction() {
  setTimeout(() => {
    // Heavy analytics processing delays upcoming button clicks:
    sendHeavyTelemetry();
  }, 0);
}

// ✅ NEW: Explicitly triage non-urgent work to the background queue,
// ensuring zero impact on user input responsiveness (INP).
function logUserInteraction() {
  scheduler.postTask(
    () => {
      sendHeavyTelemetry();
    },
    { priority: 'background' }
  );
}

// Urgent task that should jump ahead of normal work:
function renderUrgentModal() {
  return scheduler.postTask(() => renderModal(), { priority: 'user-blocking' });
}
